function renderSection() {
  const host = document.querySelector("[data-section-content]");
  if (!host) return;
  const key = document.body.dataset.section;
  const section = catalog[key] || catalog.society;
  document.title = `${section.title} — Ставрополь+`;
  const rows = section.items.map((title, index) => {
    const number = String(index + 1).padStart(2, "0");
    const minute = String(42 - index * 5).padStart(2, "0");
    return `<article class="section-row"><b>${number}</b><a href="article.html?section=${key}&story=${index + 1}"><h2>${title}</h2><p>Сегодня · ${index < 6 ? `10:${minute}` : `09:${minute}`} <span>◉ ${(16 - index) * 1000}K</span></p></a></article>`;
  }).join("");

  host.innerHTML = `<main class="shell section-page__main"><aside class="ad ad--leader" aria-label="Рекламное место"><span>Реклама</span><small>970 × 90 · лидерборд</small></aside><header class="section-intro"><p>Раздел</p><h1>${section.title}</h1><span>${section.intro}</span></header><div class="section-page__layout"><section class="section-feed" aria-label="Лента раздела"><div class="section-feed__head"><span>Сегодня</span><i></i><small>Свежее по времени</small></div>${rows}</section><aside class="section-page__rail"><div class="ad ad--square"><span>Реклама</span><small>300 × 250</small></div><section class="rail-note"><span>Подписка</span><h2>Главное за день — в одном письме</h2><p>Коротко, один раз в день. Без лишнего шума.</p><button type="button" data-subscribe>Подписаться</button></section><div class="ad ad--rail"><span>Реклама</span><small>300 × 300</small></div></aside></div><aside class="ad ad--bottom" aria-label="Рекламное место"><span>Реклама</span><small>970 × 90 · нижний баннер</small></aside></main>`;
}

renderSection();
